#!/usr/bin/env python3
"""
Reproduction script to test the progress value issue.
This script demonstrates the current limitation and will be used to verify the fix.
"""

import sys
import os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '.'))

from sepal_ui import sepalwidgets as sw

def test_current_behavior():
    """Test the current behavior that should fail with values outside [0,1]"""
    print("Testing current behavior...")

    alert = sw.Alert()

    # Test valid values (should work)
    try:
        alert.update_progress(0.0)
        print("✓ progress = 0.0 works")
    except Exception as e:
        print(f"✗ progress = 0.0 failed: {e}")

    try:
        alert.update_progress(0.5)
        print("✓ progress = 0.5 works")
    except Exception as e:
        print(f"✗ progress = 0.5 failed: {e}")

    try:
        alert.update_progress(1.0)
        print("✓ progress = 1.0 works")
    except Exception as e:
        print(f"✗ progress = 1.0 failed: {e}")

    # Test invalid values (currently fails, should work after fix)
    try:
        alert.update_progress(1.5)
        print("✓ progress = 1.5 works")
    except ValueError as e:
        print(f"✗ progress = 1.5 failed with ValueError: {e}")
    except Exception as e:
        print(f"✗ progress = 1.5 failed with unexpected error: {e}")

    try:
        alert.update_progress(50)  # Raw count
        print("✓ progress = 50 works")
    except ValueError as e:
        print(f"✗ progress = 50 failed with ValueError: {e}")
    except Exception as e:
        print(f"✗ progress = 50 failed with unexpected error: {e}")

    try:
        alert.update_progress(-0.5)
        print("✓ progress = -0.5 works")
    except ValueError as e:
        print(f"✗ progress = -0.5 failed with ValueError: {e}")
    except Exception as e:
        print(f"✗ progress = -0.5 failed with unexpected error: {e}")

def test_tqdm_compatibility():
    """Test that we can use tqdm arguments properly"""
    print("\nTesting tqdm compatibility...")

    alert = sw.Alert()

    # Test with custom total
    try:
        alert.update_progress(50, total=100)  # 50 out of 100
        print("✓ progress = 50 with total=100 works")
    except Exception as e:
        print(f"✗ progress = 50 with total=100 failed: {e}")

    # Test with custom total beyond 100
    try:
        alert.reset()  # Reset the alert
        alert.update_progress(150, total=200)  # 150 out of 200
        print("✓ progress = 150 with total=200 works")
    except Exception as e:
        print(f"✗ progress = 150 with total=200 failed: {e}")

if __name__ == "__main__":
    test_current_behavior()
    test_tqdm_compatibility()
